using System;

namespace UltrafastEngine.Schema
{
    /// <summary>
    /// Declarations of every built-in element, instrument, model and spec section: the single source of truth for
    /// the JSON Schemas (<see cref="SchemaGenerator"/>), the unknown-key checks (<see cref="Validator"/>), the
    /// reference tables (docs/reference, generated by <see cref="ReferenceGenerator"/>) and the Python type hints.
    /// A new option is added here and in the code that reads it; the test ExamplesUseOnlyDeclaredOptions keeps the
    /// two in step.
    /// </summary>
    public static partial class BuiltInOptions
    {
        private static readonly string[] Pol = { "x", "y", "45", "-45", "rcp", "lcp" };

        public static void RegisterAll(Action<ComponentSpec> add)
        {
            Sections(add);
            Elements(add);
            Instruments(add);
            Models(add);
        }

        // ================================================================== system file and run spec sections

        private static void Sections(Action<ComponentSpec> add)
        {
            add(new ComponentSpec("system", "", "An optical system: a chain of elements.").DocAt("reference/system-file.md")
                .Str("format", "\"ultrafast-system\"")
                .Int("version", "Format version", "2")
                .Str("name", "Name of the system").Str("description", "Free text")
                .Free("source", ParamType.Object, "Provenance of the file (written by exporters, e.g. the zemax plugin); free-form")
                .Obj("sampling", "Wavelengths of all per-wavelength arrays in the file", "samplingWavelengths")
                .Obj("environment", "Air of the laboratory and the index reference of quoted data", "environment")
                .Free("materials", ParamType.Object, "Materials defined in this file, by name (docs/reference/materials.md)")
                .Free("coatings", ParamType.Object, "Coatings defined in this file, by name (docs/reference/coatings.md)")
                .Model("inputBeam", "beam", "Default beam for nonlinear elements without one")
                .ListOf("elements", "element", "The beam path, in order", required: true)
                .ListOf("overrides", "override", "Changes to models or values (docs/reference/models.md#overrides)"));
            add(new ComponentSpec("samplingWavelengths", "", "Sampling wavelengths of per-wavelength arrays.")
                .Arr("wavelengthsM", "m", "Wavelengths").Arr("wavelengthsNm", "nm", "Wavelengths in nm (alternative)"));
            add(new ComponentSpec("environment", "", "Laboratory air.")
                .Enum("indexReference", new[] { "air", "vacuum" }, "Quoted data are relative to air (OpticStudio) or vacuum", "vacuum (air for zemax exports)")
                .Obj("air", "Air: temperatureC, pressurePa, humidity, co2ppm, or an index model with kind", "air"));
            add(new ComponentSpec("air", "", "Laboratory air (Ciddor).").Open()
                .Num("temperatureC", "degC", "Temperature", "20").Num("pressurePa", "Pa", "Pressure", "101325")
                .Num("humidity", "", "Relative humidity 0..1", "0").Num("co2ppm", "ppm", "CO2", "450").Str("kind", "An index model kind instead (e.g. \"ciddor\")"));
            add(new ComponentSpec("override", "", "One override (docs/reference/models.md#overrides).")
                .Str("target", "material:NAME, element:ID (trailing * wildcard), element:*, type:TYPE or global", required: true)
                .Str("property", "Property to change (lengthM, n2, index, beam, coating, timeResponse, filter, enabled, ...)", required: true)
                .P("value", ParamType.Any, "", "New value (numbers may carry a unit string: \"2.2E-20 m^2/W\")")
                .P("model", ParamType.Any, "", "New model (an object with kind, an expression, or \"@callback\")")
                .Enum("mode", new[] { "replace", "add" }, "replace, or add (time responses and filters)", "replace")
                .Str("source", "Provenance label").Str("origin", "Provenance detail"));

            add(new ComponentSpec("run", "", "A run: the pulse, the instruments and numerical settings.").DocAt("reference/run-spec.md")
                .Str("format", "\"ultrafast-run\"")
                .Int("version", "Format version", "2")
                .Str("name", "Name of the run")
                .Obj("pulse", "The input pulse", "pulse", required: true)
                .Obj("grid", "Time/frequency grid", "grid")
                .Obj("physics", "Physics switches", "physics")
                .Obj("stepper", "Nonlinear solver settings", "stepper")
                .P("probes", ParamType.Any, "", "Snapshots of the pulse: \"all\", \"end\" or a list of element ids", "\"end\"")
                .ListOf("instruments", "instrument", "Instruments")
                .ListOf("overrides", "override", "Overrides (highest priority)")
                .Model("inputBeam", "beam", "Default beam for nonlinear elements without one")
                .Obj("outputs", "Which files to write", "outputs")
                .Obj("compute", "Compute back-end and threads", "compute"));
            add(new ComponentSpec("pulse", "", "The input pulse (docs/reference/run-spec.md#pulse).")
                .Enum("shape", new[] { "gaussian", "sech2", "superGaussian", "spectrum" }, "Pulse shape", "gaussian")
                .Num("centerWavelengthM", "m", "Carrier wavelength (for spectrum: default = intensity-weighted mean)")
                .Num("centerWavelengthNm", "nm", "Carrier wavelength in nm (alternative)")
                .Num("durationFwhmS", "s", "Transform-limited intensity FWHM").Num("durationFwhmFs", "fs", "Transform-limited FWHM in fs (alternative)")
                .Num("bandwidthFwhmM", "m", "Spectral FWHM (alternative to the duration)").Num("bandwidthFwhmNm", "nm", "Spectral FWHM in nm")
                .Int("order", "superGaussian order", "2")
                .Num("energyJ", "J", "Pulse energy").Num("averagePowerW", "W", "Average power (with repRateHz)")
                .Num("peakPowerW", "W", "Peak power (alternative)").Num("repRateHz", "Hz", "Repetition rate")
                .Obj("chirp", "Spectral phase about the carrier: gddS2/todS3/fodS4 or gddFs2/todFs3/fodFs4", "chirp")
                .P("polarization", ParamType.Any, "", "\"x\", \"y\", \"45\", \"-45\", \"rcp\", \"lcp\", {angleDeg, ellipticity} or [exRe, exIm, eyRe, eyIm]", "\"x\"")
                .Obj("spectrum", "Measured spectrum (shape: spectrum): wavelengthsM + intensity (+ phaseRad), or csv", "pulseSpectrum")
                .Num("delayS", "s", "Time offset", "0")
                .P("pedestal", ParamType.Any, "", "Pedestal / contrast components: one object or a list (replica, prePulse, postPulse, ase, phaseNoise, exponential)")
                .Obj("noise", "Quantum noise on the input: one photon per frequency mode with random phase (supercontinuum coherence, parametric seeding)", "pulseNoise"));
            add(new ComponentSpec("pulseNoise", "", "Quantum noise added to the input pulse (docs/reference/fibers.md#noise-and-coherence).")
                .Enum("kind", new[] { "onePhotonPerMode", "none" }, "Noise model", "onePhotonPerMode")
                .Int("seed", "Random seed (a coherence study varies it)", "1")
                .Enum("polarization", new[] { "same", "both" }, "Noise in the pulse's polarisation only, or one photon in each of x and y", "same"));
            add(new ComponentSpec("chirp", "", "Spectral phase coefficients about the carrier.")
                .Num("gddS2", "s^2", "Group-delay dispersion").Num("todS3", "s^3", "Third-order dispersion").Num("fodS4", "s^4", "Fourth-order dispersion")
                .Num("gddFs2", "fs^2", "GDD in fs^2").Num("todFs3", "fs^3", "TOD in fs^3").Num("fodFs4", "fs^4", "FOD in fs^4"));
            add(new ComponentSpec("pulseSpectrum", "", "A measured input spectrum.")
                .Arr("wavelengthsM", "m", "Wavelengths").Arr("wavelengthsNm", "nm", "Wavelengths in nm")
                .Arr("intensity", "", "Intensity per unit wavelength").Arr("phaseRad", "rad", "Spectral phase (optional)")
                .Str("csv", "CSV file: wavelength, intensity, optional phase").Str("wavelengthUnit", "Unit of the CSV wavelength column", "nm")
                .Num("resolutionM", "m", "Resolution (Gaussian FWHM) of the spectrometer that recorded it", "0 (unknown)").Num("resolutionNm", "nm", "Resolution in nm")
                .Bool("deconvolve", "Remove the recording resolution (Richardson-Lucy) before use", "false").Int("deconvolveIterations", "Richardson-Lucy iterations", "30")
