                .Num("threshold", "", "After background subtraction, values below this fraction of the peak are set to zero", "0")
                .Describe("A measured input spectrum. Rows are sorted by wavelength, repeated wavelengths merged and non-finite rows dropped (each reported in the notes). A floor above 0.3 % of the peak that is not subtracted gives a warning. See docs/reference/measured-data.md."));
            add(new ComponentSpec("grid", "", "The time/frequency grid (docs/reference/run-spec.md#grid).")
                .Bool("auto", "Size the grid from pulse and system", "true")
                .Int("n", "Number of samples (with auto: a minimum)", "4096")
                .Num("windowS", "s", "Time window", "30 x the transform limit").Num("windowPs", "ps", "Time window in ps")
                .Int("maxN", "Largest allowed n", "4194304")
                .Bool("snapCarrier", "Put the carrier on the frequency grid", "true")
                .Num("spectralMargin", "", "Spectral span factor", "auto")
                .Num("minSpanFraction", "", "Nonlinear runs: minimum half-span / carrier", "0.1")
                .Num("minPointsPerFwhm", "", "Samples across the transform-limited FWHM", "12")
                .Num("satelliteLevel", "", "Weakest combination of ghost / replica satellites the window makes room for (relative intensity); weaker multi-satellite combinations may wrap around the window", "1e-8"));
            add(new ComponentSpec("physics", "", "Physics switches (docs/reference/run-spec.md#physics).")
                .Bool("nonlinear", "Master switch for nonlinear propagation", "true")
                .Bool("selfSteepening", "Self-steepening", "true")
                .Bool("raman", "Delayed (Raman) response of materials that have one", "true")
                .Enum("fieldMode", new[] { "auto", "envelope", "carrier" }, "Envelope or carrier-resolved (real field) propagation", "auto")
                .Num("fieldHarmonic", "", "Highest harmonic the carrier-resolved grid holds", "3")
                .Bool("absoluteIndex", "Add air dispersion to air paths quoted relative to air", "true")
                .Enum("polarization", new[] { "jones", "scalar" }, "Jones (two polarisations) or scalar", "jones")
                .Bool("losses", "false removes flat loss terms", "true")
                .P("beamTracking", ParamType.Any, "", "Gaussian beam (q) tracking: \"auto\" (on with a Gaussian inputBeam), \"on\", \"off\"", "\"auto\"")
                .Obj("transverse", "Default spatial model for every bulk/gap/crystal without one", "transverse")
                .P("ionization", ParamType.Any, "", "Photo-ionisation and plasma in every nonlinear bulk element: true or an ionization object", "false"));
            add(new ComponentSpec("ionization", "", "Photo-ionisation and plasma (docs/reference/ionization.md).")
                .Enum("model", new[] { "ppt", "adk", "mpi", "keldysh" }, "Rate model", "ppt (gases) / keldysh (solids)")
                .Num("ionizationEv", "eV", "Ionisation potential (gases)").Num("zEff", "", "Effective charge (molecules)")
                .Num("bandGapEv", "eV", "Band gap (solids)").Num("effectiveMass", "", "Reduced mass / m_e (solids)").Num("neutralDensityM3", "1/m^3", "Density of ionisable atoms / valence electrons")
                .Num("sigmaK", "(m^2/W)^K/s", "MPI cross section").Int("photons", "MPI order K")
                .Num("collisionTimeS", "s", "Electron collision time").Num("recombinationTimeS", "s", "Recombination / trapping time").Num("recombinationBetaM3PerS", "m^3/s", "Two-body recombination")
                .Bool("avalanche", "Avalanche (impact) ionisation", "true for solids").Bool("absorption", "Plasma and ionisation losses", "true").Str("species", "Gas species (when the material does not say)"));
            add(new ComponentSpec("compute", "", "Compute back-end (docs/reference/speed.md).")
