            add(new ComponentSpec("pedestalComponent", "", "A pedestal / contrast component of the input pulse (docs/reference/run-spec.md#pedestal).").Open()
                .Enum("kind", new[] { "replica", "prePulse", "postPulse", "ase", "phaseNoise", "exponential" }, "Component", required: true)
                .Num("delayS", "s", "Delay (replica; ASE envelope centre)").Num("relativeIntensity", "", "Intensity relative to the main peak").Num("relativeEnergy", "", "Energy relative to the main pulse (replica)")
                .Num("phaseRad", "rad", "Replica phase").Num("gddFs2", "fs^2", "Extra GDD of a replica").Num("gddS2", "s^2", "Extra GDD of a replica")
                .Num("durationS", "s", "ASE duration", "10e-9").Num("energyFraction", "", "ASE energy / main energy").Num("bandwidthFwhmM", "m", "Spectral FWHM of ASE / exponential pedestal").Num("bandwidthFwhmNm", "nm", "Spectral FWHM in nm").Num("centerWavelengthM", "m", "Centre of that spectrum")
                .Num("rmsRad", "rad", "Spectral phase noise rms").Num("amplitudeRms", "", "Spectral amplitude noise rms").Num("correlationNm", "nm", "Noise correlation width").Num("correlationRadPerS", "rad/s", "Noise correlation width")
                .Num("level", "", "Exponential pedestal level at the peak").Num("riseS", "s", "Exponential rise (before the peak)").Num("fallS", "s", "Exponential fall (after the peak)")
                .Int("seed", "Random seed", "1"));
            add(new ComponentSpec("stepper", "", "Nonlinear solver (docs/reference/solvers.md).")
                .Enum("method", new[] { "adaptive", "rk4ip" }, "Adaptive ERK4(3)-IP or fixed-step RK4IP", "adaptive")
                .Num("tolerance", "", "Adaptive: local relative error per step", "1e-6")
                .Num("maxPhasePerStepRad", "rad", "Fixed: max nonlinear phase per step; adaptive: initial step", "0.01")
                .Num("maxAreaChangePerStep", "", "Limit on |d ln A_eff| per step (focusing beams)", "0.05")
                .Num("minStepM", "m", "Smallest step").Num("maxStepM", "m", "Largest step")
                .Int("maxSteps", "Step limit per element").Int("steps", "Fixed number of steps (rk4ip)"));
            add(new ComponentSpec("outputs", "", "Files written by the CLI / WriteAll.")
                .Bool("json", "summary.json and provenance.json", "true").Bool("npz", "result.npz", "true").Bool("csv", "CSV files", "true")
                .Int("maxPoints", "Cap exported traces (0 = full grid incl. complex fields)", "0"));
            add(new ComponentSpec("transverse", "", "Spatial model of an element (docs/reference/spatial-models.md).")
                .Enum("model", new[] { "none", "radial", "cartesian" }, "Representation", "none")
                .Int("points", "Radial samples (cartesian: nx = ny if omitted)", "64")
                .Int("nx", "Cartesian samples in x").Int("ny", "Cartesian samples in y")
                .Num("radiusM", "m", "Radial grid extent", "extentFactor x expected radius")
                .Num("halfWidthM", "m", "Cartesian half-width").Num("halfWidthXM", "m", "Cartesian half-width in x").Num("halfWidthYM", "m", "Cartesian half-width in y")
                .Num("extentFactor", "", "Grid extent / expected beam radius", "3.5")
                .Bool("paraxial", "Paraxial diffraction operator instead of the exact one", "false")
                .Enum("transport", new[] { "auto", "exact", "rescale", "beam" }, "How a profile from before is brought in", "auto")
                .Obj("initialProfile", "The field at the first spatial element", "initialProfile")
                .Enum("polarization", new[] { "auto", "scalar", "vector" }, "Jones (vector) fields on the grid: auto = when the beam carries a y component", "auto")
                .Enum("equation", new[] { "envelope", "uppe" }, "Nonlinear coupling: paraxial envelope, or UPPE (n omega / c k_z per plane wave)", "envelope"));
            add(new ComponentSpec("initialProfile", "", "Initial transverse field.")
                .Enum("kind", new[] { "gaussian", "superGaussian", "flatTop" }, "Shape", "gaussian")
                .Int("order", "superGaussian order", "4")
                .Num("decenterXM", "m", "Decentre in x").Num("decenterYM", "m", "Decentre in y")
                .Num("tiltXRad", "rad", "Tilt about y").Num("tiltYRad", "rad", "Tilt about x")
                .Num("radiusOfCurvatureM", "m", "Wavefront radius of curvature (negative: converging)")
