            add(new ComponentSpec("material", "", "A material (docs/reference/materials.md).")
                .Str("base", "Start from a built-in material")
                .Model("index", "index", "Refractive index model")
                .Enum("indexReference", new[] { "air", "vacuum" }, "The index is relative to air or vacuum", "vacuum")
                .Num("n2", "m^2/W", "Nonlinear index")
                .Model("raman", "delayedResponse", "Raman response")
                .Num("ramanFraction", "", "Raman fraction fR")
                .Model("attenuation", "attenuation", "Absorption model")
                .Obj("lidt", "Damage threshold", "lidt")
                .Obj("gas", "A gas: species, pressureBar, temperatureK", "gas")
                .Free("crystal", ParamType.Object, "A user chi(2) crystal (docs/reference/crystals.md#user-crystals)")
                .Free("gain", ParamType.Object, "A user gain medium (docs/reference/gain.md)")
                .Num("densityKgPerM3", "kg/m^3", "Density (informational)").Str("name", "Display name")
                .P("rotationalRaman", ParamType.Any, "", "Molecular gases: false, or {species, pressureBar, temperatureK, dephasingTimeS}", "on for N2, O2, CO2, H2, air"));
            add(new ComponentSpec("lidt", "", "Laser-induced damage threshold.")
                .Num("fluenceJPerCm2", "J/cm^2", "Threshold fluence", required: true)
                .Num("pulseDurationS", "s", "Pulse duration the threshold was measured at")
                .Num("scalingExponent", "", "tau^x scaling exponent", "0.5")
                .Num("wavelengthM", "m", "Wavelength of the measurement"));
            add(new ComponentSpec("gas", "", "A gas at pressure and temperature.")
                .Str("species", "Ar, Ne, He, Kr, Xe, N2, O2, air, CO2, H2, ...", required: true)
                .Num("pressureBar", "bar", "Pressure", "1").Num("pressurePa", "Pa", "Pressure (alternative)")
                .Num("temperatureK", "K", "Temperature", "293.15"));

            // parameter groups shared by many components
            add(new ComponentSpec("group", "elementCommon", "Keys every element accepts.")
                .Str("id", "Unique id", required: true).Str("type", "Element type", required: true)
                .Str("label", "Display name").Bool("enabled", "false skips the element", "true")
                .Arr("surfaces", "", "[first, last] source surfaces (OpticStudio rows), informational")
                .Arr("wavelengthsM", "m", "Wavelengths of this element's per-wavelength arrays (default: the file's sampling)")
